def get_curriculum():
    return {
        "title": "Excel Academy Studio — Office & IT Professional",
        "total_lessons": len(LESSONS),
        "available_lessons": len(LESSONS),
        "stages": deepcopy(STAGES),
        "lessons": deepcopy(LESSONS)
    }

def get_lesson(lesson_id):
    return next((deepcopy(x) for x in LESSONS if x["id"] == lesson_id), None)
